const S=[[0,2],[1,1],[1,3],[2,0],[2,1],[2,3]];
const objs={2:[[3,13],[4,12],[5,11]],3:[[11,15],[12,16],[13,16]],5:[[9,25],[10,24],[10,25]],6:[[11,5],[12,5],[12,7]],7:[[19,11],[20,12]],8:[[1,23],[2,22],[3,22]],9:[[22,5],[23,3]]};
function norm(points){let mr=Math.min(...points.map(p=>p[0])),mc=Math.min(...points.map(p=>p[1]));return points.map(([r,c])=>[r-mr,c-mc]);}
let forms=[];
for(let refl=0;refl<2;refl++) for(let rot=0;rot<4;rot++){
 let a=S.map(([r,c])=>{if(refl)c=-c; for(let i=0;i<rot;i++) [r,c]=[c,-r];return [r,c]});
 a=norm(a);let key=a.map(p=>p.join(',')).sort().join(';'); if(!forms.some(x=>x.key===key)) forms.push({refl,rot,a,key});
}
for(let [color,pts] of Object.entries(objs)){
 console.log('color',color, 'points',pts);
 let candidates=[];
 for(let f of forms){
  let h=Math.max(...f.a.map(p=>p[0])),w=Math.max(...f.a.map(p=>p[1]));
  for(let r0=0;r0<30-h;r0++)for(let c0=0;c0<30-w;c0++){
   let cells=new Set(f.a.map(([r,c])=>`${r0+r},${c0+c}`));
   if(pts.every(([r,c])=>cells.has(`${r},${c}`))) candidates.push({f:`ref${f.refl}rot${f.rot}`,r0,c0,missing:f.a.filter(([r,c])=>!pts.some(([rr,cc])=>rr===r0+r&&cc===c0+c)).map(([r,c])=>[r0+r,c0+c]), all:f.a.map(([r,c])=>[r0+r,c0+c])});
  }
 }
 console.log(candidates.length, candidates.slice(0,15));
}
